// Bundles ameer/ (the private dashboard) into worker/ameer-assets.js so the
// Worker serves it itself, behind the owner check. Nothing in ameer/ is ever
// copied to the public Cloudflare Pages site. Run by scripts/build.mjs.
import { readFile, writeFile, readdir } from "node:fs/promises";
import { dirname, join, relative, extname } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const SRC = join(ROOT, "ameer");
const TYPES = {
  ".html": "text/html; charset=utf-8",
  ".css": "text/css; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".mjs": "text/plain; charset=utf-8",
  ".ps1": "text/plain; charset=utf-8",
};

async function walk(dir) {
  const out = [];
  for (const e of await readdir(dir, { withFileTypes: true })) {
    const p = join(dir, e.name);
    if (e.isDirectory()) out.push(...(await walk(p)));
    else if (TYPES[extname(e.name)]) out.push(p);
  }
  return out;
}

export async function bundleAmeer() {
  const assets = {};
  for (const f of (await walk(SRC)).sort()) {
    const path = "/" + relative(SRC, f).split("\\").join("/");
    assets[path] = { type: TYPES[extname(f)], body: await readFile(f, "utf8") };
  }
  const js = "// GENERATED by scripts/ameer-bundle.mjs from ameer/. Do not edit.\nexport default " + JSON.stringify(assets) + ";\n";
  await writeFile(join(ROOT, "worker", "ameer-assets.js"), js);
  return Object.keys(assets);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  console.log("ameer assets:", (await bundleAmeer()).join(", "));
}
